CREATE TABLE public.campaign_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES public.campaigns(id) ON DELETE CASCADE,user_id uuid NOT NULL,version_number integer NOT NULL,label text,description text,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campaign_id,version_number));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.campaign_versions TO authenticated;
GRANT ALL ON public.campaign_versions TO service_role;
ALTER TABLE public.campaign_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners manage campaign versions" ON public.campaign_versions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND c.user_id=auth.uid()));
CREATE TRIGGER campaign_versions_updated BEFORE UPDATE ON public.campaign_versions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE OR REPLACE FUNCTION public.create_campaign_version(p_campaign_id uuid,p_label text DEFAULT NULL,p_description text DEFAULT NULL) RETURNS public.campaign_versions LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE c public.campaigns; result public.campaign_versions; n integer; BEGIN SELECT * INTO c FROM public.campaigns WHERE id=p_campaign_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF; SELECT COALESCE(max(version_number),0)+1 INTO n FROM public.campaign_versions WHERE campaign_id=c.id; INSERT INTO public.campaign_versions(campaign_id,user_id,version_number,label,description,snapshot) VALUES(c.id,auth.uid(),n,p_label,p_description,jsonb_build_object('campaign',to_jsonb(c),'creatives',(SELECT COALESCE(jsonb_agg(to_jsonb(a)),'[]'::jsonb) FROM public.ads a WHERE a.campaign_id=c.id AND a.user_id=auth.uid()))) RETURNING * INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.restore_campaign_version(p_campaign_id uuid,p_version_id uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE v public.campaign_versions; c jsonb; item jsonb; BEGIN SELECT * INTO v FROM public.campaign_versions WHERE id=p_version_id AND campaign_id=p_campaign_id AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Version not found'; END IF; PERFORM public.create_campaign_version(p_campaign_id,'Before restore','Automatic safety backup'); c:=v.snapshot->'campaign'; UPDATE public.campaigns SET name=c->>'name',objective=c->>'objective',platform=c->>'platform',budget=(c->>'budget')::numeric,start_date=(c->>'start_date')::timestamptz,end_date=(c->>'end_date')::timestamptz,target_audience=c->'target_audience',settings=c->'settings' WHERE id=p_campaign_id AND user_id=auth.uid(); UPDATE public.ads SET campaign_id=NULL WHERE campaign_id=p_campaign_id AND user_id=auth.uid() AND id NOT IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(v.snapshot->'creatives') x); FOR item IN SELECT * FROM jsonb_array_elements(v.snapshot->'creatives') LOOP INSERT INTO public.ads(id,user_id,campaign_id,template_id,name,status,content,canvas_data,preview_url) VALUES((item->>'id')::uuid,auth.uid(),p_campaign_id,(item->>'template_id')::uuid,item->>'name','draft',item->'content',item->'canvas_data',item->>'preview_url') ON CONFLICT(id) DO UPDATE SET campaign_id=p_campaign_id,name=EXCLUDED.name,content=EXCLUDED.content,canvas_data=EXCLUDED.canvas_data,preview_url=EXCLUDED.preview_url WHERE ads.user_id=auth.uid(); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.duplicate_campaign(p_campaign_id uuid) RETURNS public.campaigns LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE source public.campaigns; result public.campaigns; BEGIN SELECT * INTO source FROM public.campaigns WHERE id=p_campaign_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF; INSERT INTO public.campaigns(user_id,name,status,platform,budget,objective,start_date,end_date,target_audience,settings) VALUES(auth.uid(),source.name||' (Copy)','draft',source.platform,source.budget,source.objective,source.start_date,source.end_date,source.target_audience,source.settings) RETURNING * INTO result; INSERT INTO public.ads(user_id,campaign_id,template_id,content,preview_url,canvas_data,name,status) SELECT auth.uid(),result.id,template_id,content,preview_url,canvas_data,name,'draft' FROM public.ads WHERE campaign_id=source.id AND user_id=auth.uid(); INSERT INTO public.campaign_versions(campaign_id,user_id,version_number,label,description,snapshot) SELECT result.id,auth.uid(),version_number,label,description,jsonb_set(snapshot,'{campaign,id}',to_jsonb(result.id)) FROM public.campaign_versions WHERE campaign_id=source.id AND user_id=auth.uid(); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_campaign_version(uuid,text,text) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.restore_campaign_version(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_campaign_version(uuid,text,text) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.restore_campaign_version(uuid,uuid) TO authenticated,service_role;